#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_ADDRESS 0x3C   // Если не заработает, попробуй 0x3D

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);

void setup() {
  Serial.begin(9600);
  
  // Сначала пишем в терминал, чтобы проверить связь
  while (!Serial) {} 
  Serial.println("Proteus 9.0: Start test");

  // Пытаемся запустить дисплей
  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDRESS)) {
    Serial.println("OLED not found!");
    // Даже если дисплей не найден, текст в терминале должен быть
    return; 
  }

  Serial.println("OLED initialized!");
  
  display.clearDisplay();
  display.setTextColor(SSD1306_WHITE);
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.println("Hello from Nano!");
  display.display();
}

void loop() {
  // Пустой цикл
}
